 use nepl3_doc_core::{check::Category as C,lower::{self,LowerError},model::*};
 let compiled=compiled()?;
 // An empty annotation is syntactically valid but semantically invalid Doc.
 // In Code it must remain foreign syntax; the following paragraph is host Doc.
 let bad=r#"article en sentence cons anno text "a" nil nil body nil"#;
 with_input(&compiled,bad,"Article",|tree,profile,b,a|{
  let proof=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;
  assert!(matches!(lower::prefix(&proof,&compiled.doc.package.schema,C::Article,profile.registry(),b,a),Err(LowerError::Shape(_))));Ok(())
 })?;
 for input in [format!("body cons code Doc {bad} cons paragraph nil nil"),format!("body cons code Doc article en sentence nil body cons code Doc {bad} nil cons paragraph nil nil")] {
  with_input(&compiled,&input,"Body",|tree,profile,b,a|{
   let proof=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;
   let value=lower::prefix(&proof,&compiled.doc.package.schema,C::Body,profile.registry(),b,a).map_err(err)?;
   assert_eq!(value.value.embeds.len(),1);
   assert!(value.value.nodes.iter().any(|n|matches!(n.kind,DocKind::Paragraph{..})));
   assert!(!value.value.nodes.iter().any(|n|matches!(n.kind,DocKind::Anno{..})));
   let foreign=&value.value.embeds[0];assert_eq!(foreign.kind,EmbedKind::Code);
   assert_eq!(foreign.closure.syntax.schema,compiled.doc.package.schema);
   assert_eq!(foreign.closure.syntax.category,"Article");
   foreign.closure.validate(profile.registry(),b,a).map_err(err)?;
   assert!(foreign.closure.syntax.bundle.nodes.iter().any(|n|n.kind=="Form:Anno")||foreign.closure.syntax.bundle.nodes.iter().any(|n|n.kind=="Form:Code"));
   let empty=SourceStore::default();let mut receiver_admission=SourceAdmission::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,&mut receiver_admission).map_err(err)?;
   let ndf=nepl3_doc_core::portable::to_value(&value,profile.registry(),&mut codec,&mut budget()).map_err(err)?;
   let bytes=nepl3_wire::encode(&ndf,&mut budget()).map_err(err)?;
   let ndf=nepl3_wire::decode(&bytes,&mut budget()).map_err(err)?;
   let decoded=nepl3_doc_core::portable::from_value(&ndf,profile.registry(),&mut codec,&mut budget()).map_err(err)?;
   let encoded=nepl3_doc_core::portable::to_value(&decoded,profile.registry(),&mut codec,&mut budget()).map_err(err)?;assert_eq!(encoded,ndf);assert_eq!(decoded.value.nodes,value.value.nodes);assert_eq!(decoded.origins,value.origins);assert_eq!(decoded.views,value.views);assert_eq!(decoded.source_maps,value.source_maps);
   println!("Doc same-alias Code retains invalid guest, independent bundle and host sibling; actual CBOR preserves closure");Ok(())
  })?;
 }
 Ok(())
}
