fn budget()->Budget{Budget::new(Limits{source_bytes:1_000_000,work:10_000_000,depth:200_000,nodes:1_000_000,allocation_units:100_000_000,output_bytes:1_000_000,diagnostics:100,events:100})}
fn value(root:DocRoot,kinds:Vec<DocKind>)->DocValue{DocValue{root,nodes:kinds.into_iter().map(|kind|DocNode{kind,origin:None,span:None}).collect(),embeds:vec![]}}
fn text()->DocKind{DocKind::Text{text:"x".into()}}
fn main()->Result<(),ShapeError>{
 // Original short shared-DAG witness: root -> shared and root -> owner -> shared.
 let dag=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Concat{inlines:vec![InlineRef(2),InlineRef(1)]},DocKind::Strong{inline:InlineRef(2)},text()]);
 let mut limits=budget().limits();limits.depth=2;let mut low=Budget::new(limits);
 assert!(matches!(dag.validate_shape(&mut low),Err(ShapeError::Stopped(StopReason::DepthLimit))));assert_eq!(low.poll(),Err(StopReason::DepthLimit));
 let mut high=budget();dag.validate_shape(&mut high)?;assert_eq!((high.usage().depth,high.usage().nodes),(3,3));
 // Reordered traversal visits long/shared chains in both directions, caller depth included.
 for count in [2,3,8,32,128] {for reverse in [false,true] {
  let mut kinds=vec![text()];for i in 1..count {let mut refs=vec![InlineRef(0),InlineRef((i-1) as u64)];if reverse{refs.reverse();}kinds.push(DocKind::Concat{inlines:refs});}
  let data=value(DocRoot::Inline(InlineRef((count-1) as u64)),kinds);let mut b=budget();
  b.with_depth_at_least(7,|b|data.validate_shape(b).map(|_|()))?;assert_eq!(b.current_depth(),0);assert_eq!(b.usage().depth,count as u64+7);assert_eq!(b.usage().nodes,count as u64);
 }}
 println!("shared DAG longest depth and active caller depth: 11 cases pass");
 // Empty sentences are valid translation values. Variant contains Sentence only.
 let empty=value(DocRoot::Sentence(SentenceRef(0)),vec![DocKind::Sentence{inlines:vec![]}]);empty.validate_shape(&mut budget())?;
 for bad in [DocKind::Paragraph{items:vec![]},DocKind::Parallel{variants:vec![]}] {
  let v=value(DocRoot::Variant(VariantRef(0)),vec![DocKind::Variant{language:"en".into(),sentence:SentenceRef(1)},bad]);
  assert!(matches!(v.validate_shape(&mut budget()),Err(ShapeError::Category{node:1,expected:Category::Sentence})));
 }
 let mut parallel=value(DocRoot::Flow(FlowRef(0)),vec![DocKind::Parallel{variants:vec![VariantRef(1),VariantRef(2)]},DocKind::Variant{language:"en".into(),sentence:SentenceRef(3)},DocKind::Variant{language:"ja".into(),sentence:SentenceRef(3)},DocKind::Sentence{inlines:vec![]}]);
 parallel.validate_shape(&mut budget())?;
 parallel.nodes[2].kind=DocKind::Variant{language:"EN".into(),sentence:SentenceRef(3)};
