 let one=value(DocRoot::Flow(FlowRef(0)),vec![DocKind::Parallel{variants:vec![VariantRef(1)]},DocKind::Variant{language:"en".into(),sentence:SentenceRef(2)},DocKind::Sentence{inlines:vec![]}]);
