 // Annotation visibility is established from nested contents, not nonempty child arrays.
 let mut annotation=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Ruby{base:InlineRef(1),reading:InlineRef(4)},DocKind::Concat{inlines:vec![InlineRef(2),InlineRef(3)]},DocKind::Text{text:String::new()},DocKind::Concat{inlines:vec![]},text()]);
 assert!(matches!(annotation.validate_shape(&mut budget()),Err(ShapeError::EmptyAnnotationPart(1))));
 annotation.nodes[2].kind=text();annotation.validate_shape(&mut budget())?;
 let no_notes=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Anno{base:InlineRef(1),notes:vec![]},text()]);
