 let empty_note=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Anno{base:InlineRef(1),notes:vec![InlineRef(2)]},text(),DocKind::Text{text:String::new()}]);
 assert!(matches!(empty_note.validate_shape(&mut budget()),Err(ShapeError::EmptyAnnotationPart(2))));
 println!("category, empty translation, case-insensitive parallel and nested annotation visibility pass");
 // Raw references never index unchecked, including narrowing on wasm32.
 let huge=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Strong{inline:InlineRef(u64::MAX)}]);
