 let cycle=value(DocRoot::Inline(InlineRef(0)),vec![DocKind::Strong{inline:InlineRef(1)},DocKind::Concat{inlines:vec![InlineRef(0)]}]);
 assert!(matches!(cycle.validate_shape(&mut budget()),Err(ShapeError::Cycle(0))));
