fn parse_source(source: &SourceSnapshot, resolved: &ResolvedParseProfile<'_>, category: &str, b: &mut Budget, a: &mut SourceAdmission) -> Result<nepl3_engine::recovery::ParseTree,String> {
    let r=resolved.registry();
    let foundation=r.selected("nepl3.foundation",1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let mut contexts=Vec::new();
    for (alias,category) in [("Doc","Article"),("Math","Expr"),("Circuit","Design"),("Grammar","Root")]{
        let owner=resolved.language(alias,b).map_err(err)?;
        contexts.push(ReaderContext{schema:owner.schema.clone(),category:category.into(),mode:"Code".into(),origins:vec![],environment:EnvironmentEntry{id:0,digest,value:value.clone()}});
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let checked=contexts.iter().map(|raw|raw.check(&mut codec,&store,r,b).map_err(err)).collect::<Result<Vec<_>,String>>()?;
        let inputs=checked.iter().zip(["Doc","Math","Circuit","Grammar"]).map(|(context,alias)|EnvironmentInput{alias,context}).collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved,&inputs,&store,&mut codec,b).map_err(|e|format!("environments: {e:?}"))?
    };
    let entry = resolved.entry("Doc", Some(category), b).map_err(err)?;
    let states=["Doc","Math","Circuit","Grammar"].map(|alias|LanguageReaderState{alias:alias.into(),state:NdfValue::Unit});
    let mut parser =
        ParseSession::new("doc-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read(
            ParseRequest {
                snapshot: &source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    loop {
        match result.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        (if operation.schema.package == "nepl3.doc.reader" { nepl3_tools::doc::reader::read } else { nepl3_reader::builtin::provider::read })(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                result = parser
                    .resume(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            ParseOutcome::Complete { tree, cursor, .. } => { assert_eq!(cursor, source.text().len() as u64); return Ok(tree); }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}

fn budget() -> Budget { Budget::new(Limits{source_bytes:10_000_000,work:100_000_000,depth:1000,nodes:1_000_000,allocation_units:500_000_000,output_bytes:10_000_000,diagnostics:1000,events:1000}) }
struct Compiled{doc:CompiledLanguage,others:Vec<nepl3_engine::package::LanguagePackage>}
fn compiled()->Result<Compiled,String>{
    let document=nepl3_tools::bootstrap::load(include_bytes!("C:/projects/NEPL3-runtime/conformance/fixtures/doc/syntax.json"),&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
    let mut doc=nepl3_tools::doc::catalog::compile(&document,"standard.doc",&mut budget(),&mut SourceAdmission::default())?;
