  let proof=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;
  let mut low=budget();let direct=lower::prefix(&proof,&compiled.doc.package.schema,C::Inline,profile.registry(),&mut low,&mut SourceAdmission::default()).map_err(err)?;
  let peak=low.usage().depth;
  let mut outer=budget();let nested=outer.with_depth_at_least(7,|b|lower::prefix(&proof,&compiled.doc.package.schema,C::Inline,profile.registry(),b,&mut SourceAdmission::default())).map_err(err)?;
  assert_eq!(direct,nested);assert_eq!(outer.usage().depth,peak+7);
