) -> Result<T, String> {
    let r = &compiled.doc.registry;
    let packages:Vec<_>=std::iter::once(&compiled.doc.package).chain(compiled.others.iter()).collect();
    // Each runtime registration identifies the actual source serving that operation.
    let implementation_for = |operation: &nepl3_core::value::OperationRef| {
        if operation.schema.package=="nepl3.doc.reader" {Digest::of(include_bytes!("C:/projects/NEPL3-runtime/tools/src/doc/reader.rs"))}
        else {Digest::of(include_bytes!("C:/projects/NEPL3-runtime/crates/foundation/reader/src/builtin/provider.rs"))}
    };
    let mut operations = Vec::new();
    for operation in packages.iter().flat_map(|p|p.reader.providers.iter().map(|v|&v.operation))
    {
        if !operations.contains(operation) {
            operations.push(operation.clone());
        }
    }
    let providers: Vec<_> = operations
        .iter()
        .map(|operation| ProviderImplementation {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operations: vec![operation.clone()],
        })
        .collect();
    let requirements = operations
        .iter()
        .map(|operation| ProviderRequirement {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operation: operation.clone(),
        })
        .collect();
    let mut schemas = packages.iter().map(|p|p.schema.clone()).collect::<Vec<_>>();
    for schema in packages.iter().flat_map(|p|p.payload_schemas.iter()).chain(
